--- /dev/null
+++ b/api/src/utils/sanitize-permissions.ts
@@ -0,0 +1,24 @@
+type Permissions = Record<string, string[] | '*' | null | boolean>;
+
+/**
+ * Sanitizes permissions JSON by removing a specific field name from all field arrays.
+ * - Arrays: filter out the field, set to null if empty
+ * - * / true / false / null: unchanged
+ */
+export default function sanitizePermissions(permissions: Permissions, fieldName: string): Permissions {
+	const sanitized: Permissions = { ...permissions };
+
+	for (const [action, value] of Object.entries(permissions)) {
+		if (Array.isArray(value)) {
+			const filtered = value.filter((field: string) => field !== fieldName && field !== `${fieldName}.*`);
+
+			sanitized[action] = filtered.length > 0 ? filtered : null;
+		}
+		// Other types (*, true, false, null) remain unchanged
+	}
+
+	return sanitized;
+}

