+      const remoteParsed = new urlModule.URL(remoteUrlStr);
+      if (
+        remoteParsed.protocol === parsed.protocol &&
+        remoteParsed.hostname.toLowerCase() === hostname &&
+        remoteParsed.port === parsed.port &&
+        remoteParsed.pathname === '/'
